from pathlib import Path
import json,html
p=Path('docs/reviews/workflow-rules-20261111');d=json.loads((p/'rules.json').read_text());groups=list(dict.fromkeys(r['group'] for r in d['rows']))
intro='''<h1>制作流程规则与验收</h1><p class="intro">48 类规则已经认可，适用部分已实施或验证保留。下方「修复前实现」保留最初只读审计，「本次验收」说明本轮结果。回执规则已确认，分类实现仍待完成；回收站已按认可方案迁入正式产品，启动不清理现有作品。<a href="../../verification/workflow-rules-implementation-20261111/acceptance-48.md">查看逐项验收矩阵</a> · <a href="../../verification/workflow-rules-implementation-20261111/REPORT.md">验收报告</a> · <a href="../../verification/recycle-bin-migration-20261111/REPORT.md">回收站迁移报告</a></p>
<section><h2>已经认可的总规则</h2><p><strong>不再使用的内容，不应继续阻塞当前作品。</strong>关闭口播、字幕、配乐或音效，应解除当前制作依赖。旧任务、可能的费用和供应商结果仍保留记录，作为独立提醒；不能因此自动重发、自动重新启用或自动采用。</p><p>「关闭提示/窗口」只收起界面；「停用/不使用」改变当前作品的需求；「取消任务」只在任务/供应商明确支持并确认后才算取消。这三种操作需要不同的名称和结果。</p></section>
<section><h2>修复前发现的问题（审计基线）</h2><ul><li>口播开关只改变原生工程并静音保留音轨，未处理旧口播任务关联；目录汇总又不看这个关闭标记，所以仍显示阻塞。</li><li>待准备计数只判断 mode 与采用音轨，没有判断 enabled，因此关闭后仍可能计入。</li><li>真正导出检查主要看已用文件、连续画面和启用字幕，与列表历史任务汇总不是同一套判断；可能出现「列表需处理但实际可导出」。</li><li>只静音仍保留原生媒体节点时，文件引用也仍存在。若「关闭」含义是舍弃，需要明确从导出依赖中排除，不能只调整音量。</li><li>口播发送前拦截与发送后断网目前都可能归为 unknown；不能据此推断本次已经发给供应商。</li></ul></section>
<section><h2>已认可的异步规则（回执分类部分暂缓）</h2><table><thead><tr><th>事实</th><th>是否阻塞</th><th>允许操作</th><th>停用当前内容后</th></tr></thead><tbody>
<tr><td>尚未发送/本机校验失败</td><td>只挡本次动作与必需依赖</td><td>修正后重新提交；不应提示已扣费</td><td>解除制作依赖，保留失败记录</td></tr>
<tr><td>明确拒绝/明确执行失败</td><td>当前必需内容仍缺失才阻塞</td><td>修正后重试原输入；新参数属新请求</td><td>保留历史，可继续制作其他内容</td></tr>
<tr><td>已排队/执行中</td><td>等待当前必需结果；其他无冲突操作可做</td><td>等待/读取状态；支持取消才可取消</td><td>从当前作品摘下；在途事实仍可见</td></tr>
<tr><td>已发送，结果未知</td><td>阻止自动重复付费；不自动阻塞不用它的导出</td><td>查原任务/供应商；必要时独立确认新付费请求</td><td>保留费用/结果核对提醒，不自动采用迟到结果</td></tr>
<tr><td>已有产物，登记未完成</td><td>尚不可当作已可用</td><td>恢复同一次产物登记，不重新生成</td><td>作为待恢复记录，不成为无关交付门槛</td></tr>
<tr><td>候选完成，未采用</td><td>只有当前必需内容还空缺才阻塞</td><td>预览/采用/舍弃；无需重试</td><td>保留候选/历史，当前作品不再等待它</td></tr>
<tr><td>已采用且当前文件有效</td><td>可继续</td><td>编辑/导出/撤回；内容变化需重新确认</td><td>解除当前引用/可执行依赖，文件历史保留</td></tr>
<tr><td>已确认交付，但后来文件损坏/缺失</td><td>不可假装可下载或已验证</td><td>读回校验或恢复该交付文件</td><td>不是「关提示就解决」，需要真实文件证据</td></tr>
</tbody></table></section>
<section><h2>实施边界</h2><ol><li>关闭口播/字幕/配乐/音效 = 不使用这部分，不再列为当前作品阻塞；保留文件与任务历史。</li><li>旧任务可能扣费但本片已不用，放在「待核对请求」提醒中，不把整张生产单标成「需处理」。</li><li>列表「需处理」只来自当前实际必需内容、当前已用文件和未解决成片问题。后台历史失败不直接升级为整期阻塞。</li><li>失败重试、查询原任务、恢复产物登记、重新付费生成，分成不同动作。</li><li>回收站默认 5 GB，超限按最早安全项目清到上限内；刚入站和单项超限保留，活动/未知任务禁止入站，共享/离线/变化项不强制清理；正式实现与隔离验收见回收站报告。</li></ol></section>'''
css='''*{box-sizing:border-box}body{margin:0;background:#eef2f8;color:#17263e;font:14px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1260px;margin:auto;padding:40px 28px 80px}h1{font-size:30px;margin:0 0 12px}h2{font-size:20px;margin:0 0 16px}p{margin:8px 0 14px}.intro{max-width:90ch;color:#596b83}section{margin-top:36px;background:#fff;padding:24px;border-radius:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #d8e1ee;padding:12px}th{color:#596b83;font-size:12px}td{min-width:100px}input,select,button{font:inherit;padding:8px 12px;border:1px solid #bdcadd;border-radius:7px;background:#fff;color:inherit}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:0 0 20px}.controls input{flex:1;min-width:180px}summary{cursor:pointer;font-weight:600}details{border-bottom:1px solid #d8e1ee;padding:16px 0}summary span{color:#596b83;font-weight:400;margin-right:12px}.facts{display:grid;grid-template-columns:128px minmax(0,1fr);gap:12px 20px;margin:20px 0}.facts dt{color:#596b83}.facts dd{margin:0}.sources{font-size:12px;color:#596b83;overflow-wrap:anywhere}code{font-size:12px}#count{color:#596b83}li{margin-bottom:8px}button{cursor:pointer}button:focus-visible,summary:focus-visible,a:focus-visible{outline:2px solid #365fe0;outline-offset:3px}::selection{background:#dce5ff}a{color:#365fe0;text-underline-offset:3px}@media(max-width:640px){main{padding:24px 12px}section{padding:18px 14px}.table-scroll{overflow:auto}.facts{grid-template-columns:1fr;gap:4px}.facts dd{margin-bottom:14px}h1{font-size:24px}}@media print{body{background:white}main{max-width:none;padding:0}section{break-inside:avoid}details{break-inside:avoid}.controls{display:none}}'''
parts=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>制作流程与操作规则审阅</title><style>'+css+'</style><main>'+intro]
parts.append('<section><h2>逐项操作清单</h2><div class="controls"><input id="query" aria-label="搜索操作或规则" placeholder="搜索：关闭、未知、重试、导出…"><select id="group" aria-label="按环节筛选"><option value="">全部环节</option>'+''.join('<option>'+html.escape(g)+'</option>' for g in groups)+'<option>只看建议变化</option></select><button id="expand">全部展开</button><button id="collapse">全部收起</button></div><p id="count"></p><div id="rows">')
for r in d['rows']:
 parts.append('<details data-group="'+r['group']+'"><summary><span>'+str(r['id'])+' · '+r['group']+'</span>'+html.escape(r['action'])+'</summary><dl class="facts">')
 for key,label in [('implementation','本次验收'),('current','修复前实现'),('passRule','规则：可以通过'),('block','规则：哪些阻塞'),('afterOff','规则：关闭/舍弃后'),('retry','规则：失败后如何继续'),('proposal','已认可的规则')]:parts.append('<dt>'+label+'</dt><dd>'+html.escape(r[key])+'</dd>')
 parts.append('</dl><p class="sources">源码依据：'+html.escape(r['source'])+'</p></details>')
parts.append('</div></section><section><h2>命令覆盖清单</h2><p>四步工作区 '+str(len(d['commands']))+' 个直接命令；另列 '+str(len(d['legacyCommands']))+' 个通用/兼容入口。共用上面的权限、版本、异步和依赖规则，未以此清单新增或放宽操作权限。</p><details><summary>查看四步工作区命令</summary><ul>')
parts.extend('<li><code>'+html.escape(c['name'])+'</code> · '+html.escape(c['source'])+'</li>' for c in d['commands'])
parts.append('</ul></details><details><summary>查看通用与兼容命令</summary><p>来源：src/local-app/episodeCommands.ts。旧流程按现存权限与基准继续读取，不将旧自动继续等同新的整期付费授权。</p><p><code>'+html.escape(', '.join(d['legacyCommands']))+'</code></p></details></section>')
parts.append('''<section><h2>证据与边界</h2><p>2026-11-11 实施前的只读现场：第二镜头的原生口播开关为 false，后台仍为 tts 且挂着旧任务；任务近乎立即进入 unknown，没有对应本次 submission/费用预留记录。前一轮隔离故障注入证明未外发与外发后断线可归为同一种异常。历史上究竟触发了哪一个分支，现有证据仍不能唯一确定。</p><p>这份清单保留审计基线，并增加本轮逐项实施和验证结果，不声称所有排列组合都已经执行过真实生成。没有重发供应商请求、清除旧任务或修改真实作品。回收站安全自动清理仅由后续显式入站或保存上限触发，升级、启动和读取不清理。</p><p>回执证据：docs/verification/settings-comments-20261111/receipt-logs/。回收站/连接/密钥 Demo：docs/verification/settings-comments-20261111/demo/。完整机器可读清单：rules.json。</p></section></main><script>const q=document.getElementById('query'),g=document.getElementById('group'),rows=[...document.querySelectorAll('#rows>details')];function filter(){let n=0;for(const r of rows){const match=(!g.value||g.value==='只看建议变化'||r.dataset.group===g.value)&&r.textContent.toLowerCase().includes(q.value.trim().toLowerCase());r.hidden=!match;if(match)n++;}document.getElementById('count').textContent='显示 '+n+' / '+rows.length+' 类场景';}q.addEventListener('input',filter);g.addEventListener('change',filter);document.getElementById('expand').onclick=()=>rows.filter(r=>!r.hidden).forEach(r=>r.open=true);document.getElementById('collapse').onclick=()=>rows.forEach(r=>r.open=false);filter();</script></html>''')
# Remove the nonfunctional filter choice; every row explicitly separates proposal from current rules.
page=''.join(parts).replace('<option>只看建议变化</option>','');(p/'index.html').write_text(page)
